sol:
printf '#!/usr/bin/env bash
case "$1" in
  start) echo starting ;;
  stop) echo stopping ;;
  *) echo "usage: $0 start|stop" ;;
esac
' > ~/scripts/menu.sh

printf '#!/usr/bin/env bash
tmp=$(mktemp -d)
cleanup() {
  rm -rf "${tmp:?}"
}
trap cleanup EXIT
log() {
  local msg=$1
  echo "$msg"
}
log "work in $tmp"
' > ~/scripts/safe.sh
